        gap: 8px;
        padding: 6px 12px;
        border-radius: 999px;
        background: rgba(79, 70, 229, 0.1);
        color: var(--brand-strong);
        font-size: 12px;
        font-weight: 700;
        letter-spacing: 0.08em;
        text-transform: uppercase;
      }

      h1 {
        margin: 14px 0 8px;
        font-size: clamp(2rem, 3vw, 3.1rem);
        line-height: 1.05;
      }

      .subtitle {
        margin: 0;
        color: var(--muted);
        font-size: 1rem;
        line-height: 1.6;
      }

      .quiz {
        display: grid;
        gap: 18px;
      }

      .form-field {
        padding: 24px;
        border: 1px solid var(--panel-border);
        border-radius: 22px;
        background: rgba(255, 255, 255, 0.92);
        box-shadow: 0 12px 30px rgba(15, 23, 42, 0.06);
      }

      .question-title {
        margin: 0 0 8px;
        font-size: 1.05rem;
      }

      .help-text {
        margin: 0 0 14px;
        color: var(--muted);
        font-size: 0.95rem;
      }

      .choices {
        display: grid;
        gap: 10px;
        margin: 0;
        padding: 0;
        list-style: none;
      }

      .choice {
        display: flex;
        align-items: flex-start;
        gap: 12px;
        padding: 14px 15px;
        border: 1px solid #dbe3f1;
        border-radius: 16px;
        background: #fff;
        transition: transform 0.15s ease, border-color 0.15s ease, box-shadow 0.15s ease;
      }

      .choice:hover {
        transform: translateY(-1px);
        border-color: rgba(79, 70, 229, 0.35);
        box-shadow: 0 8px 18px rgba(79, 70, 229, 0.08);
