            const nextChoices = currentChoices.includes(choice)
              ? currentChoices.filter((item) => item !== choice)
              : [...currentChoices, choice];

            return {
              ...current,
              [questionId]: nextChoices
            };
          });
        }

        function handleSubmit(event) {
          event.preventDefault();
          setSubmitted(true);
        }

        return h(
          "main",
          { className: "page" },
          h(
            "section",
            { className: "hero" },
            h("div", { className: "eyebrow" }, "Knowledge check"),
            h("h1", null, "Computer Languages Quiz"),
            h(
              "p",
              { className: "subtitle" },
              "Choose all answers that apply for each question, then submit your selections."
            )
          ),
          h(
            "form",
            { className: "quiz", onSubmit: handleSubmit },
