              "div",
              { className: "actions" },
              h("button", { className: "submit-btn", type: "submit" }, "Submit Quiz")
            ),
            submitted
              ? h(
                  "div",
                  { className: "result", role: "status" },
                  "Your answers have been submitted."
                )
              : null
          )
        );
      }

      ReactDOM.createRoot(document.getElementById("root")).render(h(QuizApp));
