 <!DOCTYPE html>
 <html lang="en">
   <head>
     <meta charset="UTF-8" />
     <meta name="viewport" content="width=device-width, initial-scale=1.0" />
     <title>Computer Languages Quiz</title>
     <script src="https://unpkg.com/react@18/umd/react.development.js"></script>
     <script src="https://unpkg.com/react-dom@18/umd/react-dom.development.js"></script>
     <style>
       :root {
         color-scheme: light;
         --bg: #f4f7fb;
         --panel: rgba(255, 255, 255, 0.88);
         --panel-border: rgba(148, 163, 184, 0.24);
         --text: #0f172a;
         --muted: #475569;
         --brand: #4f46e5;
         --brand-strong: #4338ca;
         --shadow: 0 18px 45px rgba(15, 23, 42, 0.1);
       }

       * {
         box-sizing: border-box;
       }

       body {
         margin: 0;
         min-height: 100vh;
         font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
         color: var(--text);
         background:
           radial-gradient(circle at top left, rgba(79, 70, 229, 0.14), transparent 30%),
           radial-gradient(circle at top right, rgba(14, 165, 233, 0.12), transparent 25%),
           linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
       }

       .page {
         max-width: 900px;
         margin: 0 auto;
         padding: 48px 20px 64px;
       }

       .hero {
         margin-bottom: 24px;
         padding: 28px 30px;
         border: 1px solid var(--panel-border);
         border-radius: 24px;
         background: var(--panel);
         box-shadow: var(--shadow);
         backdrop-filter: blur(14px);
       }

       .eyebrow {
         display: inline-flex;
         align-items: center;
         gap: 8px;
         padding: 6px 12px;
         border-radius: 999px;
         background: rgba(79, 70, 229, 0.1);
         color: var(--brand-strong);
         font-size: 12px;
         font-weight: 700;
         letter-spacing: 0.08em;
         text-transform: uppercase;
       }

       h1 {
         margin: 14px 0 8px;
         font-size: clamp(2rem, 3vw, 3.1rem);
         line-height: 1.05;
       }

       .subtitle {
         margin: 0;
         color: var(--muted);
         font-size: 1rem;
         line-height: 1.6;
       }

       .quiz {
         display: grid;
         gap: 18px;
       }

       .form-field {
         padding: 24px;
         border: 1px solid var(--panel-border);
         border-radius: 22px;
         background: rgba(255, 255, 255, 0.92);
         box-shadow: 0 12px 30px rgba(15, 23, 42, 0.06);
       }

       .question-title {
         margin: 0 0 8px;
         font-size: 1.05rem;
       }

       .help-text {
         margin: 0 0 14px;
         color: var(--muted);
         font-size: 0.95rem;
       }

       .choices {
         display: grid;
         gap: 10px;
         margin: 0;
         padding: 0;
         list-style: none;
       }

       .choice {
         display: flex;
         align-items: flex-start;
         gap: 12px;
         padding: 14px 15px;
         border: 1px solid #dbe3f1;
         border-radius: 16px;
         background: #fff;
         transition: transform 0.15s ease, border-color 0.15s ease, box-shadow 0.15s ease;
       }

       .choice:hover {
         transform: translateY(-1px);
         border-color: rgba(79, 70, 229, 0.35);
         box-shadow: 0 8px 18px rgba(79, 70, 229, 0.08);
       }

       .choice input {
         margin-top: 3px;
         accent-color: var(--brand);
       }

       .choice span {
         font-size: 0.98rem;
         line-height: 1.45;
       }

       .actions {
         margin-top: 18px;
         display: flex;
         justify-content: flex-end;
       }

       .submit-btn {
         border: 0;
         border-radius: 14px;
         padding: 14px 20px;
         background: linear-gradient(135deg, var(--brand), var(--brand-strong));
         color: #fff;
         font-size: 1rem;
         font-weight: 700;
         cursor: pointer;
         box-shadow: 0 12px 24px rgba(79, 70, 229, 0.28);
       }

       .submit-btn:hover {
         filter: brightness(1.03);
       }

       .result {
         margin-top: 18px;
         padding: 16px 18px;
         border-radius: 16px;
         background: rgba(79, 70, 229, 0.08);
         color: var(--text);
         font-weight: 600;
       }

       @media (max-width: 640px) {
         .page {
           padding: 20px 14px 40px;
         }

         .hero,
         .form-field {
           padding: 20px;
           border-radius: 18px;
         }
       }
     </style>
   </head>
   <body>
     <div id="root"></div>

     <script>
       const h = React.createElement;
       const { useMemo, useState } = React;

       const questions = [
         {
           id: "q1",
           prompt: "Which of these are programming languages?",
           help: "Select every option that is a computer language.",
           choices: ["Python", "HTML", "Java", "Ruby"]
         },
         {
           id: "q2",
           prompt: "Which languages are commonly used for web development?",
           choices: ["JavaScript", "C", "CSS", "TypeScript"]
         },
         {
           id: "q3",
           prompt: "Which of these are compiled programming languages?",
           choices: ["Go", "Kotlin", "Markdown", "C++"]
         }
       ];

       function QuestionField({ question, selected, onToggle }) {
         return h(
           "div",
           { className: "form-field" },
           h("h2", { className: "question-title" }, question.prompt),
           question.help ? h("p", { className: "help-text" }, question.help) : null,
           h(
             "ul",
             { className: "choices" },
             question.choices.map((choice, index) =>
               h(
                 "li",
                 { key: choice, className: "choice" },
                 h("input", {
                   type: "checkbox",
                   checked: selected.includes(choice),
                   onChange: () => onToggle(question.id, choice)
                 }),
                 h("span", null, choice)
               )
             )
           )
         );
       }

       function QuizApp() {
         const initialState = useMemo(
           () =>
             Object.fromEntries(
               questions.map((question) => [question.id, []])
             ),
           []
         );
         const [answers, setAnswers] = useState(initialState);
         const [submitted, setSubmitted] = useState(false);

         function toggleAnswer(questionId, choice) {
           setSubmitted(false);
           setAnswers((current) => {
             const currentChoices = current[questionId] || [];
             const nextChoices = currentChoices.includes(choice)
               ? currentChoices.filter((item) => item !== choice)
               : [...currentChoices, choice];

             return {
               ...current,
               [questionId]: nextChoices
             };
           });
         }

         function handleSubmit(event) {
           event.preventDefault();
           setSubmitted(true);
         }

         return h(
           "main",
           { className: "page" },
           h(
             "section",
             { className: "hero" },
             h("div", { className: "eyebrow" }, "Knowledge check"),
             h("h1", null, "Computer Languages Quiz"),
             h(
               "p",
               { className: "subtitle" },
               "Choose all answers that apply for each question, then submit your selections."
             )
           ),
           h(
             "form",
             { className: "quiz", onSubmit: handleSubmit },
             questions.map((question) =>
               h(QuestionField, {
                 key: question.id,
                 question,
                 selected: answers[question.id],
                 onToggle: toggleAnswer
               })
             ),
             h(
               "div",
               { className: "actions" },
               h("button", { className: "submit-btn", type: "submit" }, "Submit Quiz")
             ),
             submitted
               ? h(
                   "div",
                   { className: "result", role: "status" },
                   "Your answers have been submitted."
                 )
               : null
           )
         );
       }

       ReactDOM.createRoot(document.getElementById("root")).render(h(QuizApp));
     </script>
   </body>
 </html>

